import { expect, test, uniqueName, sample } from "../../fixtures";

test.describe("upload vendor documents", () => {
  const cases = [
    { label: "an empty file", kind: "w9", status: 422, code: "empty_file", file: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) } },
    { label: "a file of exactly 10 MiB + 1", kind: "w9", status: 413, code: "file_too_large", file: { name: "big.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(10 * 1024 * 1024 + 1, 0x41) } },
    { label: "a .exe file", kind: "w9", status: 415, code: "unsupported_type", file: { name: "setup.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ\u0000\u0000 not really an exe") } },
    { label: "a valid text file", kind: "passport", status: 422, code: "validation_error", file: { name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("hello vendor\n") } },
  ];

  for (const c of cases) {
    test(`rejects ${c.label} with ${c.code}`, { tag: "@DOC-04" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Doc Vendor"),
          category: "services",
          contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
        },
      });
      expect(created.status(), await created.text()).toBe(201);
      const vendor = await created.json();

      // Act
      const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: { kind: c.kind, file: c.file },
      });

      // Assert
      const body = await res.text();
      expect(res.status(), body).toBe(c.status);
      expect(JSON.parse(body).error?.code, body).toBe(c.code);
    });
  }
});
